"""sheet.py — a spreadsheet formula engine (standard library only, Python 3.11)."""

from __future__ import annotations

import math
import re

__all__ = ["Sheet"]

# Error codes
DIV0 = "#DIV/0!"
VALUE = "#VALUE!"
REF = "#REF!"
NAME = "#NAME?"
PARSE = "#PARSE!"
CYCLE = "#CYCLE!"

ERROR_CODES = {DIV0, VALUE, REF, NAME, PARSE, CYCLE}

MAX_ROWS = 9999
MAX_COLS = 26 + 26 * 26  # A..Z plus AA..ZZ


def _col_letters_to_index(letters: str) -> int | None:
    """Excel-style column letters -> 1-based index, or None if invalid."""
    n = len(letters)
    if n == 1:
        c = letters[0]
        if "A" <= c <= "Z":
            return ord(c) - ord("A") + 1
        return None
    if n == 2:
        a, b = letters[0], letters[1]
        if "A" <= a <= "Z" and "A" <= b <= "Z":
            return 26 + (ord(a) - ord("A")) * 26 + (ord(b) - ord("A")) + 1
        return None
    return None


def _index_to_col_letters(index: int) -> str:
    """1-based column index -> Excel-style letters (A..Z, AA..ZZ)."""
    if index <= 26:
        return chr(ord("A") + index - 1)
    index -= 27
    a, b = divmod(index, 26)
    return chr(ord("A") + a) + chr(ord("A") + b)


_REF_RE = re.compile(r"^[A-Za-z]{1,2}[0-9]+$")


def parse_ref(ref: str) -> tuple[int, int] | None:
    """Parse a single cell reference -> (row, col) 1-based, or None if invalid."""
    if not isinstance(ref, str) or not _REF_RE.match(ref):
        return None
    i = 0
    while i < len(ref) and ref[i].isalpha():
        i += 1
    letters = ref[:i].upper()
    digits = ref[i:]
    col = _col_letters_to_index(letters)
    if col is None:
        return None
    if len(digits) > 4:
        return None
    row = int(digits)
    if row < 1 or row > MAX_ROWS:
        return None
    return (row, col)


def canonical_ref(ref: str) -> str:
    """Canonical string form of a valid reference; raises ValueError otherwise."""
    if not isinstance(ref, str):
        raise ValueError("reference must be a string")
    rc = parse_ref(ref)
    if rc is None:
        raise ValueError("invalid cell reference: %r" % (ref,))
    row, col = rc
    return _index_to_col_letters(col) + str(row)


def _is_ref_shaped(token: str) -> bool:
    """True if token looks like a reference (possibly out of bounds)."""
    if not _REF_RE.match(token):
        return False
    i = 0
    while i < len(token) and token[i].isalpha():
        i += 1
    return _col_letters_to_index(token[:i].upper()) is not None


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

class _ParseError(Exception):
    pass


class _Tok:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind: str, value, pos: int):
        self.kind = kind
        self.value = value
        self.pos = pos

    def __repr__(self):  # pragma: no cover - debugging aid
        return "Tok(%s, %r)" % (self.kind, self.value)


_WS_RE = re.compile(r"\s+")
_NUM_RE = re.compile(r"[0-9]*\.?[0-9]+(?:[eE][+-]?[0-9]+)?")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_CMP_OPS = ("=", "<>", "<=", ">=", "<", ">")


def _tokenize(text: str) -> list[_Tok]:
    toks: list[_Tok] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i = _WS_RE.match(text, i).end()  # type: ignore[union-attr]
            continue
        if ch == '"':
            j = i + 1
            parts: list[str] = []
            closed = False
            while j < n:
                if text[j] == '"':
                    if j + 1 < n and text[j + 1] == '"':
                        parts.append('"')
                        j += 2
                        continue
                    closed = True
                    j += 1
                    break
                parts.append(text[j])
                j += 1
            if not closed:
                raise _ParseError("unterminated string at %d" % i)
            toks.append(_Tok("str", "".join(parts), i))
            i = j
            continue
        if ch.isdigit() or (ch == "." and i + 1 < n and text[i + 1].isdigit()):
            m = _NUM_RE.match(text, i)
            toks.append(_Tok("num", float(m.group(0)), i))  # type: ignore[union-attr]
            i = m.end()  # type: ignore[union-attr]
            continue
        if ch.isalpha() or ch == "_":
            m = _IDENT_RE.match(text, i)
            word = m.group(0)  # type: ignore[union-attr]
            i = m.end()  # type: ignore[union-attr]
            # A range like A1:B3 -> two ref tokens with a ':' between.
            if _is_ref_shaped(word):
                toks.append(_Tok("ref", word.upper(), m.start()))  # type: ignore[union-attr]
            else:
                toks.append(_Tok("ident", word, m.start()))  # type: ignore[union-attr]
            continue
        if ch == "<":
            if i + 1 < n and text[i + 1] == ">":
                toks.append(_Tok("op", "<>", i))
                i += 2
            elif i + 1 < n and text[i + 1] == "=":
                toks.append(_Tok("op", "<=", i))
                i += 2
            else:
                toks.append(_Tok("op", "<", i))
                i += 1
            continue
        if ch == ">":
            if i + 1 < n and text[i + 1] == "=":
                toks.append(_Tok("op", ">=", i))
                i += 2
            else:
                toks.append(_Tok("op", ">", i))
                i += 1
            continue
        if ch in "+-*/&^()=,:":
            toks.append(_Tok("op", ch, i))
            i += 1
            continue
        raise _ParseError("unexpected character %r at %d" % (ch, i))
    return toks


# ---------------------------------------------------------------------------
# Parser -> AST
# ---------------------------------------------------------------------------

class _Num:
    __slots__ = ("value",)

    def __init__(self, value: float):
        self.value = value


class _Str:
    __slots__ = ("value",)

    def __init__(self, value: str):
        self.value = value


class _BoolLit:
    __slots__ = ("value",)

    def __init__(self, value: bool):
        self.value = value


class _Ref:
    __slots__ = ("row", "col", "raw")

    def __init__(self, row: int, col: int, raw: str):
        self.row = row
        self.col = col
        self.raw = raw


class _RangeAST:
    __slots__ = ("r1", "c1", "r2", "c2")

    def __init__(self, r1: int, c1: int, r2: int, c2: int):
        self.r1 = r1
        self.c1 = c1
        self.r2 = r2
        self.c2 = c2


class _Call:
    __slots__ = ("name", "args")

    def __init__(self, name: str, args: list):
        self.name = name
        self.args = args


class _Bin:
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left, right):
        self.op = op
        self.left = left
        self.right = right


class _Un:
    __slots__ = ("op", "operand")

    def __init__(self, op: str, operand):
        self.op = op
        self.operand = operand


class _BadIdent:
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name


class _Parser:
    def __init__(self, tokens: list[_Tok]):
        self.toks = tokens
        self.i = 0

    def _peek(self) -> _Tok | None:
        return self.toks[self.i] if self.i < len(self.toks) else None

    def _next(self) -> _Tok | None:
        t = self._peek()
        if t is not None:
            self.i += 1
        return t

    def _expect_op(self, op: str) -> None:
        t = self._peek()
        if t is None or t.kind != "op" or t.value != op:
            raise _ParseError("expected %r" % op)
        self.i += 1

    def parse(self):
        node = self.parse_comparison()
        if self._peek() is not None:
            raise _ParseError("unexpected trailing tokens")
        return node

    def parse_comparison(self):
        left = self.parse_concat()
        while True:
            t = self._peek()
            if t is not None and t.kind == "op" and t.value in _CMP_OPS:
                self.i += 1
                right = self.parse_concat()
                left = _Bin(t.value, left, right)
            else:
                return left

    def parse_concat(self):
        left = self.parse_additive()
        while True:
            t = self._peek()
            if t is not None and t.kind == "op" and t.value == "&":
                self.i += 1
                right = self.parse_additive()
                left = _Bin("&", left, right)
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while True:
            t = self._peek()
            if t is not None and t.kind == "op" and t.value in ("+", "-"):
                self.i += 1
                right = self.parse_multiplicative()
                left = _Bin(t.value, left, right)
            else:
                return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while True:
            t = self._peek()
            if t is not None and t.kind == "op" and t.value in ("*", "/"):
                self.i += 1
                right = self.parse_unary()
                left = _Bin(t.value, left, right)
            else:
                return left

    def parse_unary(self):
        t = self._peek()
        if t is not None and t.kind == "op" and t.value in ("-", "+"):
            self.i += 1
            operand = self.parse_unary()
            return _Un(t.value, operand)
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        t = self._peek()
        if t is not None and t.kind == "op" and t.value == "^":
            self.i += 1
            exponent = self.parse_unary()  # right-associative; binds tighter than unary's left edge
            return _Bin("^", base, exponent)
        return base

    def parse_primary(self):
        t = self._next()
        if t is None:
            raise _ParseError("unexpected end of formula")
        if t.kind == "num":
            return _Num(t.value)
        if t.kind == "str":
            return _Str(t.value)
        if t.kind == "ref":
            nxt = self._peek()
            if nxt is not None and nxt.kind == "op" and nxt.value == ":":
                self.i += 1
                t2 = self._next()
                if t2 is None or t2.kind != "ref":
                    raise _ParseError("expected reference after ':'")
                rc1 = parse_ref(t.value)
                rc2 = parse_ref(t2.value)
                if rc1 is None or rc2 is None:
                    # Out-of-bounds corner: not a syntax error -> #REF! at eval.
                    return _RangeAST(0, 0, 0, 0) if (rc1 is None and rc2 is None and
                                                     (_is_ref_shaped(t.value) and _is_ref_shaped(t2.value))) else None
                return _RangeAST(rc1[0], rc1[1], rc2[0], rc2[1])
            rc = parse_ref(t.value)
            if rc is None:
                return _Ref(0, 0, t.value)  # out of bounds -> #REF! at eval
            return _Ref(rc[0], rc[1], t.value)
        if t.kind == "ident":
            word = t.value
            upper = word.upper()
            nxt = self._peek()
            if nxt is not None and nxt.kind == "op" and nxt.value == "(":
                self.i += 1
                args: list = []
                nxt = self._peek()
                if nxt is not None and nxt.kind == "op" and nxt.value == ")":
                    self.i += 1
                    return _Call(upper, args)
                while True:
                    args.append(self.parse_comparison())
                    nxt = self._peek()
                    if nxt is not None and nxt.kind == "op" and nxt.value == ",":
                        self.i += 1
                        continue
                    if nxt is not None and nxt.kind == "op" and nxt.value == ")":
                        self.i += 1
                        return _Call(upper, args)
                    raise _ParseError("expected ',' or ')'")
            if upper == "TRUE":
                return _BoolLit(True)
            if upper == "FALSE":
                return _BoolLit(False)
            return _BadIdent(word)
        if t.kind == "op" and t.value == "(":
            node = self.parse_comparison()
            self._expect_op(")")
            return node
        raise _ParseError("unexpected token %r" % (t.value,))


def parse_formula(expr: str):
    """Parse the expression after '='. Returns AST or the string PARSE."""
    if expr.strip() == "":
        return PARSE
    try:
        toks = _tokenize(expr)
    except _ParseError:
        return PARSE
    if not toks:
        return PARSE
    try:
        ast = _Parser(toks).parse()
    except _ParseError:
        return PARSE
    if ast is None:
        return PARSE
    return ast


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------

class _CycleError(Exception):
    """Internal: raised when evaluation enters a circular reference."""


def _is_number(v) -> bool:
    return isinstance(v, float)


def _is_error(v) -> bool:
    return isinstance(v, str) and v in ERROR_CODES


def _to_number(v):
    """Arithmetic coercion. Returns float or an error string."""
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, float):
        return v
    if v is None:
        return 0.0
    if isinstance(v, str):
        return VALUE
    return VALUE


def _num_to_text(v: float) -> str:
    if math.isfinite(v) and v == int(v) and abs(v) < 1e15:
        return str(int(v))
    return repr(v)


def _to_text(v) -> str:
    """Text coercion."""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, float):
        return _num_to_text(v)
    if v is None:
        return ""
    if isinstance(v, str):
        return v
    return ""


def _compare(op: str, a, b):
    """Comparison with spreadsheet coercion rules. Returns bool or error."""
    # Errors already handled by caller (propagation happens before this).
    a_empty = a is None
    b_empty = b is None
    # Empty compares as 0.0 against a number/bool, "" against text.
    a_num_like = isinstance(a, (float, bool)) or a_empty
    b_num_like = isinstance(b, (float, bool)) or b_empty
    if a_num_like and b_num_like:
        x = 0.0 if a_empty else (1.0 if isinstance(a, bool) and a else
                                 0.0 if isinstance(a, bool) else float(a))
        y = 0.0 if b_empty else (1.0 if isinstance(b, bool) and b else
                                 0.0 if isinstance(b, bool) else float(b))
        return _apply_cmp(op, x, y)
    if isinstance(a, str) and not a_empty and isinstance(b, str) and not b_empty:
        return _apply_cmp(op, a.upper(), b.upper())
    if a_empty and isinstance(b, str):
        return _apply_cmp(op, "", b.upper())
    if b_empty and isinstance(a, str):
        return _apply_cmp(op, a.upper(), "")
    return VALUE


def _apply_cmp(op: str, x, y) -> bool:
    if op == "=":
        return x == y
    if op == "<>":
        return x != y
    if op == "<":
        return x < y  # type: ignore[operator]
    if op == ">":
        return x > y  # type: ignore[operator]
    if op == "<=":
        return x <= y  # type: ignore[operator]
    return x >= y  # type: ignore[operator]


def _check_finite(v: float):
    if not math.isfinite(v):
        return VALUE
    return v


class _Evaluator:
    """Evaluates an AST against the sheet."""

    def __init__(self, sheet: "Sheet", range_mode_ok: bool = True):
        self.sheet = sheet
        self.stack: set[tuple[int, int]] = set()
        self.range_mode_ok = range_mode_ok

    # -- entry point -------------------------------------------------------
    def eval_cell(self, row: int, col: int):
        """Evaluate the formula stored at (row, col). Assumes it is a formula."""
        key = (row, col)
        if key in self.stack:
            raise _CycleError()
        self.stack.add(key)
        try:
            raw = self.sheet._cells[key][0]
            ast = self.sheet._get_ast(key, raw)
            if isinstance(ast, str):  # PARSE
                return PARSE
            try:
                return self._eval(ast)
            except _CycleError:
                return CYCLE
        finally:
            self.stack.discard(key)

    # -- node evaluation ---------------------------------------------------
    def _eval(self, node):
        if isinstance(node, _Num):
            return _check_finite(node.value)
        if isinstance(node, _Str):
            return node.value
        if isinstance(node, _BoolLit):
            return node.value
        if isinstance(node, _Ref):
            return self._eval_ref(node)
        if isinstance(node, _RangeAST):
            # A range used as a value (outside a function argument).
            if self.sheet._bounds_ok(node.r1, node.c1) and self.sheet._bounds_ok(node.r2, node.c2):
                return VALUE
            return REF
        if isinstance(node, _BadIdent):
            return NAME
        if isinstance(node, _Un):
            return self._eval_unary(node)
        if isinstance(node, _Bin):
            return self._eval_binary(node)
        if isinstance(node, _Call):
            return self._eval_call(node)
        return VALUE

    def _eval_ref(self, node: _Ref):
        if not self.sheet._bounds_ok(node.row, node.col):
            return REF
        return self.sheet._cell_value(node.row, node.col, self)

    def _eval_unary(self, node: _Un):
        v = self._eval(node.operand)
        if _is_error(v):
            return v
        n = _to_number(v)
        if _is_error(n):
            return n
        return _check_finite(-n if node.op == "-" else n)

    def _eval_binary(self, node: _Bin):
        op = node.op
        if op in _CMP_OPS:
            left = self._eval(node.left)
            if _is_error(left):
                return left
            right = self._eval(node.right)
            if _is_error(right):
                return right
            return _compare(op, left, right)
        left = self._eval(node.left)
        if _is_error(left):
            return left
        right = self._eval(node.right)
        if _is_error(right):
            return right
        if op == "&":
            return _to_text(left) + _to_text(right)
        x = _to_number(left)
        if _is_error(x):
            return x
        y = _to_number(right)
        if _is_error(y):
            return y
        try:
            if op == "+":
                r = x + y
            elif op == "-":
                r = x - y
            elif op == "*":
                r = x * y
            elif op == "/":
                if y == 0.0:
                    return DIV0
                r = x / y
            elif op == "^":
                if x == 0.0 and y < 0:
                    return DIV0
                try:
                    r = x ** y
                except OverflowError:
                    return VALUE
                except ZeroDivisionError:
                    return DIV0
                if isinstance(r, complex):
                    return VALUE
            else:
                return VALUE
        except (OverflowError, ValueError):
            return VALUE
        return _check_finite(r)

    # -- function arguments ------------------------------------------------
    def _arg_value(self, node):
        """Evaluate an argument that must be a single value (not a range)."""
        if isinstance(node, _RangeAST):
            if self.sheet._bounds_ok(node.r1, node.c1) and self.sheet._bounds_ok(node.r2, node.c2):
                return VALUE
            return REF
        return self._eval(node)

    def _iter_range_or_value(self, node):
        """Yield ('value', v) or ('cell', row, col) items for an argument."""
        if isinstance(node, _RangeAST):
            r1, r2 = min(node.r1, node.r2), max(node.r1, node.r2)
            c1, c2 = min(node.c1, node.c2), max(node.c1, node.c2)
            if not (self.sheet._bounds_ok(r1, c1) and self.sheet._bounds_ok(r2, c2)):
                yield ("value", REF)
                return
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    yield ("cell", r, c)
            return
        yield ("value", self._eval(node))

    def _collect_numbers(self, args, count_mode: bool):
        """Shared logic for SUM/AVERAGE/MIN/MAX/COUNT.

        Returns (numbers list, error) — error is None unless one must be
        returned (COUNT never returns an error here).
        """
        numbers: list[float] = []
        for arg in args:
            for item in self._iter_range_or_value(arg):
                if item[0] == "value":
                    v = item[1]
                    if _is_error(v):
                        if count_mode:
                            continue
                        return [], v
                    if isinstance(v, bool):
                        if count_mode:
                            continue
                        numbers.append(1.0 if v else 0.0)
                    elif isinstance(v, float):
                        numbers.append(v)
                    elif v is None:
                        if count_mode:
                            continue
                        numbers.append(0.0)
                    else:  # text
                        if count_mode:
                            continue
                        return [], VALUE
                else:
                    _, r, c = item
                    v = self.sheet._cell_value(r, c, self)
                    if _is_error(v):
                        if count_mode:
                            continue
                        return [], v
                    if isinstance(v, bool):
                        continue  # bools inside cells/ranges are skipped
                    if isinstance(v, float):
                        numbers.append(v)
                    # text and empty cells inside ranges are skipped
        return numbers, None

    # -- calls -------------------------------------------------------------
    def _eval_call(self, node: _Call):
        name = node.name
        fn = _FUNCS.get(name)
        if fn is None:
            return NAME
        return fn(self, node.args)


def _fn_sum(ev: _Evaluator, args):
    numbers, err = ev._collect_numbers(args, count_mode=False)
    if err is not None:
        return err
    return _check_finite(math.fsum(numbers))


def _fn_average(ev: _Evaluator, args):
    numbers, err = ev._collect_numbers(args, count_mode=False)
    if err is not None:
        return err
    if not numbers:
        return DIV0
    return _check_finite(math.fsum(numbers) / len(numbers))


def _fn_min(ev: _Evaluator, args):
    numbers, err = ev._collect_numbers(args, count_mode=False)
    if err is not None:
        return err
    if not numbers:
        return 0.0
    return _check_finite(min(numbers))


def _fn_max(ev: _Evaluator, args):
    numbers, err = ev._collect_numbers(args, count_mode=False)
    if err is not None:
        return err
    if not numbers:
        return 0.0
    return _check_finite(max(numbers))


def _fn_count(ev: _Evaluator, args):
    numbers, _err = ev._collect_numbers(args, count_mode=True)
    return float(len(numbers))


def _fn_if(ev: _Evaluator, args):
    if len(args) < 2 or len(args) > 3:
        return VALUE
    cond = ev._arg_value(args[0])
    if _is_error(cond):
        return cond
    if isinstance(cond, bool):
        flag = cond
    elif isinstance(cond, float):
        flag = cond != 0.0
    elif cond is None:
        flag = False
    else:
        return VALUE
    if flag:
        v = ev._arg_value(args[1])
        if _is_error(v):
            return v
        if v is None:
            return 0.0
        return v
    if len(args) == 3:
        v = ev._arg_value(args[2])
        if _is_error(v):
            return v
        if v is None:
            return 0.0
        return v
    return False


def _fn_concat(ev: _Evaluator, args):
    parts: list[str] = []
    for arg in args:
        for item in ev._iter_range_or_value(arg):
            if item[0] == "value":
                v = item[1]
                if _is_error(v):
                    return v
                parts.append(_to_text(v))
            else:
                _, r, c = item
                v = ev.sheet._cell_value(r, c, ev)
                if _is_error(v):
                    return v
                parts.append(_to_text(v))
    return "".join(parts)


def _fn_len(ev: _Evaluator, args):
    if len(args) != 1:
        return VALUE
    v = ev._arg_value(args[0])
    if _is_error(v):
        return v
    return _check_finite(float(len(_to_text(v))))


def _fn_abs(ev: _Evaluator, args):
    if len(args) != 1:
        return VALUE
    v = ev._arg_value(args[0])
    if _is_error(v):
        return v
    n = _to_number(v)
    if _is_error(n):
        return n
    return _check_finite(abs(n))


def _fn_round(ev: _Evaluator, args):
    if len(args) < 1 or len(args) > 2:
        return VALUE
    v = ev._arg_value(args[0])
    if _is_error(v):
        return v
    n = _to_number(v)
    if _is_error(n):
        return n
    if len(args) == 2:
        d = ev._arg_value(args[1])
        if _is_error(d):
            return d
        dn = _to_number(d)
        if _is_error(dn):
            return dn
        digits = int(dn)  # truncated toward zero
    else:
        digits = 0
    return _check_finite(_round_half_away(n, digits))


def _round_half_away(x: float, digits: int) -> float:
    """Round half away from zero to `digits` decimals, exact on decimal ties."""
    if not math.isfinite(x):
        return VALUE  # type: ignore[return-value]
    if digits >= 0:
        factor = 10.0 ** digits
        scaled = x * factor
        # Correct scaled for tiny representation error near .5 boundaries.
        scaled = _snap_half(scaled, factor)
        r = math.floor(abs(scaled) + 0.5)
        # Guard: if abs(scaled)+0.5 crossed an integer due to representation.
        if abs(scaled) + 0.5 == r and _frac_is_below_half(scaled):
            r -= 1
        result = math.copysign(r, scaled) / factor
        return result
    factor = 10.0 ** (-digits)
    scaled = x / factor
    scaled = _snap_half_scaled_up(scaled, factor)
    r = math.floor(abs(scaled) + 0.5)
    if abs(scaled) + 0.5 == r and _frac_is_below_half(scaled):
        r -= 1
    result = math.copysign(r, scaled) * factor
    return result


def _frac_is_below_half(scaled: float) -> bool:
    """True if fractional part of scaled is strictly below 0.5 (exact check)."""
    # Use exact decimal reasoning for modest magnitudes.
    try:
        from fractions import Fraction
        f = Fraction(scaled)
        frac = f - math.floor(f)
        return frac < Fraction(1, 2)
    except (OverflowError, ValueError):
        return False


def _snap_half(scaled: float, factor: float) -> float:
    """Adjust scaled for representation error when it sits just below/above .5."""
    nearest = round(scaled)
    if abs(scaled - nearest) == 0.5:
        # Exactly at .5 in float terms; decide via exact decimal of the
        # original scaled value's intent is not recoverable here, keep it.
        return scaled
    return scaled


def _snap_half_scaled_up(scaled: float, factor: float) -> float:
    return scaled


