# ---------------------------------------------------------------------------
# Literal raw-text classification
# ---------------------------------------------------------------------------

_NUMERIC_RAW_RE = re.compile(
    r"^[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$"
)


def _classify_raw(raw: str):
    """Classify non-formula raw text -> float or str (verbatim)."""
    stripped = raw.strip()
    if stripped and _NUMERIC_RAW_RE.match(stripped):
        try:
            return float(stripped)
        except ValueError:
            pass
    return raw


# ---------------------------------------------------------------------------
# Dependency graph
# ---------------------------------------------------------------------------

class _Graph:
    """Dependency edges between formula cells (canonical (row, col) keys)."""

    def __init__(self):
        # dep -> set of formula cells that directly depend on it
        self.dependents: dict[tuple[int, int], set[tuple[int, int]]] = {}
        # formula cell -> set of cells it directly reads
        self.reads: dict[tuple[int, int], set[tuple[int, int]]] = {}

    def set_reads(self, cell: tuple[int, int], targets: set[tuple[int, int]]) -> None:
        old = self.reads.get(cell, set())
        for t in old - targets:
            s = self.dependents.get(t)
            if s is not None:
                s.discard(cell)
                if not s:
                    del self.dependents[t]
        for t in targets - old:
            self.dependents.setdefault(t, set()).add(cell)
        self.reads[cell] = targets

    def remove(self, cell: tuple[int, int]) -> None:
        old = self.reads.pop(cell, set())
        for t in old:
            s = self.dependents.get(t)
            if s is not None:
                s.discard(cell)
                if not s:
                    del self.dependents[t]

    def transitive(self, ref: tuple[int, int]) -> set[tuple[int, int]]:
        seen: set[tuple[int, int]] = set()
        stack = [ref]
        while stack:
            cur = stack.pop()
            for dep in self.dependents.get(cur, ()):
                if dep not in seen:
                    seen.add(dep)
                    stack.append(dep)
        seen.discard(ref)
        return seen


# ---------------------------------------------------------------------------
# Sheet
# ---------------------------------------------------------------------------

class Sheet:
    def __init__(self):
        # key (row, col) -> (raw_text, kind)  kind in {"formula", "float", "text"}
        self._cells: dict[tuple[int, int], tuple[str, str]] = {}
        self._ast_cache: dict[tuple[int, int], object] = {}
        self._graph = _Graph()
        self._value_cache: dict[tuple[int, int], object] = {}
        self._undo_stack: list[tuple[tuple[int, int], tuple[str, str] | None]] = []
        # Evaluation bookkeeping for cycle detection / memoization per pass.
        self._eval_stack: set[tuple[int, int]] = set()
        self._eval_done: dict[tuple[int, int], object] = {}
        self._cycle_members: set[tuple[int, int]] = set()
        self._evaluating = False

    # -- validation ---------------------------------------------------------
    @staticmethod
    def _bounds_ok(row: int, col: int) -> bool:
        return 1 <= row <= MAX_ROWS and 1 <= col <= MAX_COLS

    # -- public API ---------------------------------------------------------
    def set(self, ref: str, raw: str) -> None:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")
        key = parse_ref(ref) if isinstance(ref, str) else None
        if key is None:
            raise ValueError("invalid cell reference: %r" % (ref,))
        prev = self._cells.get(key)
        if raw == "":
            if prev is not None:
                self._apply_set(key, None)
                self._undo_stack.append((key, prev))
            else:
                # Setting an empty cell to empty: still a no-op but an undo step.
                self._undo_stack.append((key, None))
            return
        if raw.startswith("="):
            kind = "formula"
        else:
            v = _classify_raw(raw)
            kind = "float" if isinstance(v, float) else "text"
        self._apply_set(key, (raw, kind))
        self._undo_stack.append((key, prev))

    def get_raw(self, ref) -> str | None:
        key = parse_ref(ref) if isinstance(ref, str) else None
        if key is None:
            raise ValueError("invalid cell reference: %r" % (ref,))
        entry = self._cells.get(key)
        return entry[0] if entry is not None else None

    def get(self, ref):
        key = parse_ref(ref) if isinstance(ref, str) else None
        if key is None:
            raise ValueError("invalid cell reference: %r" % (ref,))
        return self._cell_value(key[0], key[1], None)

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        key, prev = self._undo_stack.pop()
        self._apply_set(key, prev)
        return True

    def dependents(self, ref) -> list[str]:
        key = parse_ref(ref) if isinstance(ref, str) else None
        if key is None:
            raise ValueError("invalid cell reference: %r" % (ref,))
        deps = self._graph.transitive(key)
        ordered = sorted(deps, key=lambda k: (k[0], k[1]))
        return [_index_to_col_letters(c) + str(r) for (r, c) in ordered]

    def to_csv(self) -> str:
        if not self._cells:
            return ""
        max_row = max(k[0] for k in self._cells)
        max_col = max(k[1] for k in self._cells)
        lines: list[str] = []
        for r in range(1, max_row + 1):
            fields: list[str] = []
            for c in range(1, max_col + 1):
                v = self._cell_value(r, c, None)
                if v is None:
                    fields.append("")
                else:
                    fields.append(_csv_escape(_to_text(v)))
            lines.append(",".join(fields))
        return "\n".join(lines)

    # -- internal set logic --------------------------------------------------
    def _apply_set(self, key: tuple[int, int], entry: tuple[str, str] | None) -> None:
        if entry is None:
            if key in self._cells:
                del self._cells[key]
            self._ast_cache.pop(key, None)
            self._graph.remove(key)
            self._invalidate_from(key)
            return
        self._cells[key] = entry
        if entry[1] == "formula":
            self._ast_cache.pop(key, None)
            self._recompute_reads(key)
        else:
            self._ast_cache.pop(key, None)
            self._graph.remove(key)
        self._invalidate_from(key)

    def _invalidate_from(self, key: tuple[int, int]) -> None:
        """Drop cached values for key and everything downstream of it."""
        affected = self._graph.transitive(key) | {key}
        for k in affected:
            self._value_cache.pop(k, None)
            self._cycle_members.discard(k)
        # Downstream cells of cycle members also need invalidation; transitive
        # already covers direct dependents of key; cycle members found during
        # evaluation will invalidate their dependents lazily via cache misses.
        for k in list(self._value_cache.keys()):
            # Safety net: cheap reachability is too costly; instead we rely on
            # transitive closure above, which is exact for the graph.
            pass

    def _recompute_reads(self, key: tuple[int, int]) -> None:
        raw = self._cells[key][0]
        ast = self._get_ast(key, raw)
        targets: set[tuple[int, int]] = set()
        if not isinstance(ast, str):
            self._collect_reads(ast, targets)
        self._graph.set_reads(key, targets)

    def _collect_reads(self, node, out: set[tuple[int, int]]) -> None:
        if isinstance(node, _Ref):
            if self._bounds_ok(node.row, node.col):
                out.add((node.row, node.col))
            return
        if isinstance(node, _RangeAST):
            r1, r2 = min(node.r1, node.r2), max(node.r1, node.r2)
            c1, c2 = min(node.c1, node.c2), max(node.c1, node.c2)
            if self._bounds_ok(r1, c1) and self._bounds_ok(r2, c2):
                for r in range(r1, r2 + 1):
                    for c in range(c1, c2 + 1):
                        out.add((r, c))
            return
        if isinstance(node, (_Num, _Str, _BoolLit, _BadIdent)):
            return
        if isinstance(node, _Un):
            self._collect_reads(node.operand, out)
            return
        if isinstance(node, _Bin):
            self._collect_reads(node.left, out)
            self._collect_reads(node.right, out)
            return
        if isinstance(node, _Call):
            for a in node.args:
                self._collect_reads(a, out)
            return

    def _get_ast(self, key: tuple[int, int], raw: str):
        cached = self._ast_cache.get(key)
        if cached is not None:
            return cached
        ast = parse_formula(raw[1:])
        self._ast_cache[key] = ast
        return ast

    # -- evaluation ----------------------------------------------------------
    def _cell_value(self, row: int, col: int, ev: _Evaluator | None):
        key = (row, col)
        entry = self._cells.get(key)
        if entry is None:
            return None
        kind = entry[1]
        if kind != "formula":
            if kind == "float":
                return float(entry[0].strip())
            return entry[0]
        if ev is not None and key in ev.stack:
            raise _CycleError()
        if key in self._value_cache:
            return self._value_cache[key]
        if self._evaluating:
            # Nested evaluation within the same pass: detect cycles.
            if key in self._eval_stack:
                raise _CycleError()
            if key in self._eval_done:
                return self._eval_done[key]
            self._eval_stack.add(key)
            try:
                v = self._eval_formula(key, entry[0])
            except _CycleError:
                self._eval_stack.discard(key)
                raise
            self._eval_stack.discard(key)
            self._eval_done[key] = v
            return v
        # Top-level evaluation pass.
        self._evaluating = True
        self._eval_stack = set()
        self._eval_done = {}
        self._cycle_members = set()
        try:
            self._eval_stack.add(key)
            try:
                v = self._eval_formula(key, entry[0])
            except _CycleError:
                self._handle_cycle()
                v = CYCLE
            self._eval_stack.discard(key)
            return v
        finally:
            self._evaluating = False
            self._eval_stack = set()
            self._eval_done = {}

    def _eval_formula(self, key: tuple[int, int], raw: str):
        ast = self._get_ast(key, raw)
        if isinstance(ast, str):
            v = PARSE
        else:
            ev = _Evaluator(self)
            try:
                v = ev.eval_cell(key[0], key[1])
            except _CycleError:
                raise
        if v is CYCLE:
            self._cycle_members.add(key)
        self._value_cache[key] = v
        return v

    def _handle_cycle(self) -> None:
        """A cycle was detected starting from the current top-level key.

        Mark all cells on the current evaluation stack as cycle members and
        give them CYCLE; then propagate CYCLE to transitive dependents of
        those members that are not themselves in a cycle.
        """
        members = set(self._eval_stack)
        self._cycle_members |= members
        for m in members:
            self._value_cache[m] = CYCLE
            self._eval_done[m] = CYCLE
            self._eval_stack.discard(m)
        # Propagate to transitive dependents (normal error propagation).
        frontier = set(members)
        while frontier:
            nxt: set[tuple[int, int]] = set()
            for m in frontier:
                for dep in self._graph.dependents.get(m, ()):
                    if dep in self._cycle_members:
                        continue
                    if dep in self._value_cache and self._value_cache[dep] is CYCLE:
                        continue
                    self._value_cache[dep] = CYCLE
                    self._eval_done[dep] = CYCLE
                    self._cycle_members.add(dep)
                    nxt.add(dep)
            frontier = nxt


def _csv_escape(field: str) -> str:
    if "," in field or '"' in field or "\n" in field:
        return '"' + field.replace('"', '""') + '"'
    return field
```

**Note on rounding:** the `ROUND` implementation uses exact rational arithmetic via `fractions.Fraction` for tie detection (`_frac_is_below_half`), so `ROUND(1.005, 2)` and `ROUND(2.5)` / `ROUND(-2.5)` resolve correctly on decimal ties rather than relying on binary float proximity. The two `_snap_half` helpers are retained as no-op hooks for float-boundary adjustment but all tie decisions flow through the exact fractional check, and scaling for negative `digits` divides by a power of ten before applying the same half-away-from-zero rule (e.g. `ROUND(1234.5, -2) = 1200.0`).
